import CMigration
import Darwin

let HUMANVALSTR_LEN = 5
let NO_PRINT = 1

extension ls {


  func IS_NOPRINT(_ p : FTSEntry) -> Bool {
    return p.number == NO_PRINT
  }

  /* Most of these are taken from <sys/stat.h> */
  enum Colors : Int {
    case DIR			/* directory */
    case LNK			/* symbolic link */
    case SOCK			/* socket */
    case FIFO			/* pipe */
    case EXEC			/* executable */
    case BLK			/* block special */
    case CHR			/* character special */
    case SUID			/* setuid executable */
    case SGID			/* setgid executable */
    case WSDIR		/* directory writeble to others, with sticky
                   * bit */
    case WDIR			/* directory writeble to others, without
                   * sticky bit */
    case DATALESS		/* dataless file */

    case NUMCOLORS		/* just a place-holder */
  }

  static let defcolors = Array("exfxcxdxbxegedabagacadah")

  /* colors for file types */
  struct Color {
    var num : [Int] = [0, 0]
    var bold = false
  }


  func printscol(_ dp : DISPLAY) {
    if unix2003_compat, let dpl = dp.list?.first {
      if dpl.level != CMigration.FTS_ROOTLEVEL && (options.f_longform || options.f_size) {
        let n = howmany(Int(dp.btotal), Int(options.blocksize))
        print("total \(n)")
      }
    }

    for p in dp.list! {
      if (IS_NOPRINT(p)) {
        continue;
      }
      let _ = printaname(p, Int(dp.s_inode), Int(dp.s_block))
      print("")
    }
  }

  /*
   * print name in current style
   */
  @discardableResult func printname(_ name : String) -> Int {
    if (options.f_octal || options.f_octal_escape) {
      return prn_octal(name);
    }
    else if (options.f_nonprint) {
      return prn_printable(name);
    }
    else {
      return prn_normal(name);
    }
  }

  func get_abmon(_ mon : Int) -> String {
    switch (mon) {
      case 0: return String(cString: nl_langinfo(ABMON_1))
      case 1: return String(cString: nl_langinfo(ABMON_2))
      case 2: return String(cString: nl_langinfo(ABMON_3))
      case 3: return String(cString: nl_langinfo(ABMON_4))
      case 4: return String(cString: nl_langinfo(ABMON_5))
      case 5: return String(cString: nl_langinfo(ABMON_6))
      case 6: return String(cString: nl_langinfo(ABMON_7))
      case 7: return String(cString: nl_langinfo(ABMON_8))
      case 8: return String(cString: nl_langinfo(ABMON_9))
      case 9: return String(cString: nl_langinfo(ABMON_10))
      case 10: return String(cString: nl_langinfo(ABMON_11))
      case 11: return String(cString: nl_langinfo(ABMON_12))
      default: abort() // should never happen
    }
  }

  func mbswidth(_ month : String) -> Int {
//    wchar_t wc;
//    size_t width, donelen, clen, w;

    var width = 0
    var donelen = 0
    while true {
      var wc = wchar_t(0)
      let clen = month.withCString { mm in
        mbrtowc(&wc, mm + donelen, Int(MB_LEN_MAX), nil)
      }
      if clen == 0 { break }
      if clen == -1 || clen == -2 {
        return -1
      }
      donelen += clen
      let w = wcwidth(wc)
      if w == -1 {
        return -1
      }
      width += Int(w)
    }

    return width
  }

  func compute_abbreviated_month_size() {
    var months_width = Array(repeating: size_t(0), count: 12)

    for i in 0 ..< 12 {
      let width = mbswidth(get_abmon(i))
      if width == -1 {
        r.month_max_size = -1
        return
      }
      months_width[i] = width;
      if (width > r.month_max_size) {
        r.month_max_size = width;
      }
    }

    for i in 0 ..< 12 {
      r.padding_for_month[i] = r.month_max_size - months_width[i];
    }
  }

  struct ACLPermFlags : OptionSet {
    var rawValue : Int32

    static let DIR = Self(rawValue: 1)
    static let FILE = Self(rawValue: 2)
  }
  /*
   * print access control list
   */
  struct ACLPerm {
    var perm : acl_perm_t
    var name : String
    var flags : ACLPermFlags

    init(_ perm: acl_perm_t, _ name : String, _ flags : ACLPermFlags) {
      self.perm = perm
      self.name = name
      self.flags = flags
    }
  }

  static let acl_perms : [ACLPerm] = [
    .init(ACL_READ_DATA,		"read",		.FILE),
    .init(ACL_LIST_DIRECTORY,	"list",		.DIR),
    .init(ACL_WRITE_DATA,	"write",	.FILE),
    .init(ACL_ADD_FILE,		"add_file",	.DIR),
    .init(ACL_EXECUTE,		"execute",	.FILE),
    .init(ACL_SEARCH,		"search",	.DIR),
    .init(ACL_DELETE,		"delete",	[.FILE, .DIR]),
    .init(ACL_APPEND_DATA,	"append",	.FILE),
    .init(ACL_ADD_SUBDIRECTORY,	"add_subdirectory", .DIR),
    .init(ACL_DELETE_CHILD,	"delete_child",	.DIR),
    .init(ACL_READ_ATTRIBUTES,	"readattr",	[.FILE, .DIR]),
    .init(ACL_WRITE_ATTRIBUTES,	"writeattr",	[.FILE, .DIR]),
    .init(ACL_READ_EXTATTRIBUTES, "readextattr",	[.FILE, .DIR]),
    .init(ACL_WRITE_EXTATTRIBUTES, "writeextattr", [.FILE, .DIR]),
    .init(ACL_READ_SECURITY,	"readsecurity",	[.FILE, .DIR]),
    .init(ACL_WRITE_SECURITY,	"writesecurity", [.FILE, .DIR]),
    .init(ACL_CHANGE_OWNER,	"chown",	[.FILE, .DIR]),
  ]

  struct ACLFlag {
    var flag : acl_flag_t
    var name : String
    var flags : ACLPermFlags

    init(_ flag : acl_flag_t, _ name : String, _ flags : ACLPermFlags) {
      self.flag = flag
      self.name = name
      self.flags = flags
    }
  }

  static let acl_flags : [ACLFlag] = [
    .init(ACL_ENTRY_FILE_INHERIT, 	"file_inherit",		.DIR),
    .init(ACL_ENTRY_DIRECTORY_INHERIT,	"directory_inherit",	.DIR),
    .init(ACL_ENTRY_LIMIT_INHERIT,	"limit_inherit",	[.FILE, .DIR]),
    .init(ACL_ENTRY_ONLY_INHERIT,	"only_inherit",		[.DIR]),
  ]

  func uuid_to_name(_ uu : uuid_t) -> String {
    let MAXNAMETAG = MAXLOGNAME + 6 /* + strlen("group:") */

    if !options.f_numericonly {
      let (e, k) = mbr_identifier_translate(.UUID(uu), .NAME)
      if let k, case let .NAME(type, recname) = k {
        return "\(type == .USER ? "user" : "group")):\(recname)"
      }
    }

    var uux = uu
    let name : String = withUnsafeTemporaryAllocation(of: CChar.self, capacity: Int(MAXNAMETAG)) { p in
      uuid_unparse_upper(&uux, p.baseAddress!)
      let h : String = String(cString: p.baseAddress!)
      return h
    }
    return name
  }

  func printxattr(_ dp : DISPLAY, _ buf : any Sequence<(String, Int)>) {
    for ns in buf {
      print("", terminator: "\t")
      printname(ns.0)
      print("", terminator: "\t")
      printsize(Int(dp.s_size), UInt(ns.1))
      print("")
    }
  }

  func printacl(_ acl : acl_t, _ isdir : Bool) {
    var entry : acl_entry_t? = nil
    var tag = acl_tag_t(0)
    var flags = acl_flagset_t(bitPattern: 0)
    var perms = acl_permset_t(bitPattern: 0)

    /*
     int		index;
     uuid_t		*applicable;
     char		*name = NULL;
     acl_tag_t	tag;
     acl_flagset_t	flags;
     acl_permset_t	perms;
     char		*type;
     int		i, first;
     */

    var index = -1
    while acl_get_entry(acl, (entry == nil ? ACL_FIRST_ENTRY : ACL_NEXT_ENTRY).rawValue, &entry) == 0 {
      index += 1
      if acl_get_tag_type(entry, &tag) != 0 {
        continue;
      }
      if acl_get_flagset_np(UnsafeMutableRawPointer(entry), &flags) != 0 {
        continue
      }
      if acl_get_permset(entry, &perms) != 0 {
        continue;
      }

      guard let applicable = acl_get_qualifier(entry) else {
        continue
      }

      let name = uuid_to_name(applicable.assumingMemoryBound(to: uuid_t.self).pointee)
      acl_free(applicable)

      var type : String
      switch tag {
        case ACL_EXTENDED_ALLOW:
          type = "allow"
        case ACL_EXTENDED_DENY:
          type = "deny"
        default:
          type = "unknown";
      }

      let ih = acl_get_flag_np(flags, ACL_ENTRY_INHERITED) != 0 ? " inherited" : ""
      print(" \(index): \(name)\(ih) \(type) ", terminator: "")

      var first = ""
      for api in Self.acl_perms  {
        if acl_get_perm_np(perms, api.perm) == 0 {
          continue
        }
        if !api.flags.contains(isdir ? .DIR : .FILE) {
          continue
        }
        print("\(first)\(api.name)", terminator: "")
        first = ","
      }

      for afi in Self.acl_flags {
        if acl_get_flag_np(flags, afi.flag) == 0 {
          continue
        }
        if !afi.flags.contains(isdir ? .DIR : .FILE) {
          continue
        }
        print("\(first)\(afi.name)", terminator: "")
        first = ","
      }

      print("")
    }

  }

  func printlong(_ dp : DISPLAY) {
    /*
     struct stat *sp;
     FTSENT *p;
     NAMES *np;
     char buf[20];
     */

    var color_printed = false

    if ((dp.list == nil || dp.list![0].level != CMigration.FTS_ROOTLEVEL) &&
        (options.f_longform || options.f_size)) {
      print("total \(howmany(Int(dp.btotal), Int(options.blocksize)))")
    }

    for p in dp.list! {
      if IS_NOPRINT(p) {
        continue
      }
      let sp = p.statp
      if options.f_inode {
        let k = String(sp.inode).leftPad(toLength: Int(dp.s_inode))
        print("%*ju ", dp.s_inode, sp.inode)
      }
      if (options.f_size) {
        print("%*lld ", dp.s_block, howmany(Int(sp.blocks), Int(options.blocksize)), terminator: "")
      }

      var buf = strmode(sp.filetype, sp.permissions).prefix(10) /* make +/@ about the mode */

      guard let np = p.getPointer(NAMES.self) else {
        fatalError()
      }

      let str = np.mode_suffix == nil ? "" : String(np.mode_suffix!.rawValue)

      if options.f_group && options.f_owner {	/* means print neither */
        print("\(buf)\(str) %*ju   ", dp.s_nlink, sp.links, terminator: "")
      } else if options.f_group {
        print("\(buf)\(str) %*ju %-*s  ", dp.s_nlink, sp.links, dp.s_group, np.group!, terminator: "")
      } else if options.f_owner {
        print("\(buf)\(str) %*ju %-*s  ", dp.s_nlink, sp.links, dp.s_user, np.user!, terminator: "")
      } else {
        print("\(buf)\(str) %*ju %-*s  %-*s  ", dp.s_nlink, sp.links, dp.s_user, np.user!, dp.s_group,
              np.group!, terminator: "")
      }

      if options.f_flags {
        print(np.flags!.rightPad(toLength: Int(dp.s_flags)), terminator: " ")
      }

      if sp.filetype == .characterDevice || sp.filetype == .blockDevice { //  S_ISCHR(sp->st_mode) || S_ISBLK(sp->st_mode)) {
        printdev(Int(dp.s_size), Int32(sp.rawDevice))
      }
      else {
        printsize(Int(dp.s_size), sp.size)
      }
      if (options.f_accesstime) {
        printtime(sp.lastAccess.secs)
      }
      else if (options.f_birthtime) {
        printtime(sp.created.secs)
      }
      else if (options.f_statustime) {
        printtime(sp.lastModification.secs)
      }
      else {
        printtime(sp.lastWrite.secs)
      }

      if (options.f_color) {
        color_printed = colortype(sp.filetype, sp.permissions, sp.flags)
      }

      printname(p.name)

      if (options.f_color && color_printed) {
        endcolor(0)
      }

      if (options.f_type) {
        printtype(sp.filetype, sp.permissions)
      }
      if sp.filetype == .symbolicLink {
        printlink(p)
      }
      print("")

      if (np.attr_names.count != 0 && options.f_xattr) {
        printxattr(dp, zip(np.attr_names, np.xattr_sizes))
      }
      if (np.acl != nil && options.f_acl) {
        printacl(np.acl!, sp.filetype == .directory)
      }

    }
  }

  func printstream(_ dp : DISPLAY) {
    var chcnt = 0
    var cns = dp.list?.count ?? 0
    for p in dp.list ?? [] {
      cns -= 1
      if p.number == NO_PRINT {
        continue
      }
      /* XXX strlen does not take octal escapes into account. */
      var islast = cns == 0 // (p == dp.list!.last)
      if (p.name.count + chcnt + (islast ? 2 : 0))  >= options.termwidth {
        print("")
        chcnt = 0
      }
      chcnt += printaname(p, Int(dp.s_inode), Int(dp.s_block))
      if !islast {
        print(", ", terminator: "")
        chcnt += 2
      }
    }
    if chcnt != 0 {
      print("")
    }
  }
}

// FIXME: copied from df.  Promote to CMigration
public extension String {
  func leftPad(toLength: Int, withPad: String = " ") -> String {
    guard toLength > 0 else { return self }
    guard !self.isEmpty else { return String(repeating: withPad, count: toLength) }
    let paddingNeeded = toLength - self.count
    guard paddingNeeded > 0 else { return self }
    return String(repeating: withPad, count: paddingNeeded) + self
  }

  func rightPad(toLength: Int, withPad: String = " ") -> String {
    guard toLength > 0 else { return self }
    guard !self.isEmpty else { return String(repeating: withPad, count: toLength) }
    let paddingNeeded = toLength - self.count
    guard paddingNeeded > 0 else { return self }
    return self + String(repeating: withPad, count: paddingNeeded)
  }
}
